function synthHoroscope(e){
 const ctx=e?.context||{},age=ctx.age==null?null:num(ctx.age,null),houses=arr(e?.houses),domains=arr(e?.domains),dashas=arr(e?.dashas);
 const build=lang=>{
  const c={...ctx,age};
  const intro=lang==='ta'?'இந்த அறிக்கையின் இரண்டு முக்கிய பகுதிகளும் AI இல்லாத deterministic ஜோதிட விதிகளால் உருவாக்கப்படுகின்றன. முதல் பகுதி பிறப்பு ஜாதகத்தின் 12 பாவங்கள் காட்டும் மனித உறவுகள், குணநிலை, உடல் கவனம் மற்றும் பொருள்/வசதி வாழ்க்கையை ஒரே வாழ்க்கை வாசிப்பாக இணைக்கிறது. உடல்/நோய்/விபத்து குறித்த வரிகள் உறுதி செய்யப்பட்ட மருத்துவ prediction அல்ல; கவன காலம் மற்றும் பாதுகாப்பு வழிகாட்டல் மட்டும். இரண்டாவது பகுதி அதே வாக்குறுதியை தசா–புக்தி மற்றும் கோச்சார காலத்துடன் இணைத்து எப்போது, எப்படி வெளிப்படலாம் என்பதை விளக்குகிறது.':'Both main sections are produced by deterministic, non-AI astrology rules. The first integrates the twelve houses into lived personality, relationships, body-care and material-life interpretation. Health/illness/accident language is not a medical certainty; it marks periods for extra care and safety. The second combines the same natal promise with Dasha–Bhukti and transit timing to explain when and how it may manifest.';
  const life=houses.slice().sort((a,b)=>num(a.house)-num(b.house)).map(h=>v251HouseChapter(h,c,lang));
  const timingAreas=domains.map(d=>v251DomainTiming(d,e,lang)).filter(Boolean);
  const phases=dashas.slice(0,12).map((z,i)=>v251Phase(z,e,lang,i));
  const care=v251CareWindows(e,lang);if(care)timingAreas.push(care);
  return {intro,context:contextSummary(c,lang),life,timing:{intro:lang==='ta'?'இந்தப் பகுதியில் தசா பெரிய பின்னணியாகவும், புக்தி அருகிலுள்ள செயல்பாட்டு துறையாகவும், கோச்சாரம் அதன் வேகம்/பொறுப்பு/முடிவு நேரத்தை மாற்றும் துணை காரணியாகவும் வாசிக்கப்படுகிறது. ஒவ்வொரு காலமும் Career மட்டும் அல்லாமல் உறவு, குடும்பம், உடல்நலம், கடன், சொத்து, வாகனம், கல்வி, பயணம், லாபம் மற்றும் ஆன்மிகம் ஆகிய அனைத்துடனும் இணைக்கப்படுகிறது.':'Here Mahadasha is the larger background, Bhukti is the nearer active area, and transit modifies pace, responsibility or decision timing. Each phase is connected not only with career but also relationship, family, health, debt, property/vehicle, education, travel, gains and spirituality.',phases,areas:timingAreas}};
 };
 return {ok:true,nonAI:true,engine:HOROSCOPE_VERSION,ta:build('ta'),en:build('en')};
}

